// Implement a discrete PID controller with output clamping and anti-windup (clamped integrator).
// C99, MISRA-C compliant, no dynamic allocation, float arithmetic.
// Implement exactly:
//   void pid_init(pid_t *p, float kp, float ki, float kd, float dt, float out_min, float out_max);
//   float pid_update(pid_t *p, float setpoint, float measured);
#include <stdint.h>
