    float kp;
    float ki;
    float kd;
    float out_min;
    float out_max;
    float integ;
    float prev_err;
    float dt;
} pid_t;

// Implement a counter-based button debouncer sampled at fixed intervals.
// Reports stable state after DEBOUNCE_COUNT consecutive identical raw samples.
// C99, MISRA-C compliant:
//   #define DEBOUNCE_COUNT 5u
//   typedef struct { uint8_t stable_state; uint8_t last_raw; uint8_t counter; } debounce_t;
//   void debounce_init(debounce_t *d, uint8_t initial_state);
//   uint8_t debounce_update(debounce_t *d, uint8_t raw_sample); // returns stable state (0 or 1)
#include <stdint.h>
#define DEBOUNCE_COUNT 5u
typedef struct { uint8_t stable_state; uint8_t last_raw; uint8_t counter; } debounce_t;

// Implement an integer moving-average filter over a window of 8 samples using a circular buffer.
// C99, MISRA-C compliant, no dynamic allocation, no floating point:
//   #define MA_WINDOW 8u
//   typedef struct { int32_t buf[MA_WINDOW]; uint32_t idx; int32_t sum; uint32_t count; } mavg_t;
//   void mavg_init(mavg_t *m);
//   int32_t mavg_update(mavg_t *m, int32_t sample); // returns current average
#include <stdint.h>
#define MA_WINDOW 8u
typedef struct { int32_t buf[MA_WINDOW]; uint32_t idx; int32_t sum; uint32_t count; } mavg_t;
